func (entry FunctionRelease) Claim() (release.FunctionClaim, error) {
	envelope, err := trust.DecodeEnvelope(entry.Envelope)
	if err != nil {
		return release.FunctionClaim{}, err
	}
	if _, err := trust.DecodeEnvelope(entry.Delegation); err != nil {
		return release.FunctionClaim{}, err
	}
	var claim release.FunctionClaim
	if err := json.Unmarshal(envelope.Payload, &claim, json.RejectUnknownMembers(true)); err != nil {
		return release.FunctionClaim{}, err
	}
	if err := claim.Validate(); err != nil {
		return release.FunctionClaim{}, err
	}
	canonical, err := trust.EncodePayload(claim)
	if err != nil || !bytes.Equal(canonical, envelope.Payload) || envelope.Scope != release.FunctionScope(claim) {
		return release.FunctionClaim{}, ErrInvalid
	}
	return claim, nil
}

func decodeFunctionChannel(wire []byte) (FunctionChannel, error) {
	var channel FunctionChannel
	if len(wire) > MaxFunctionChannelBytes || json.Unmarshal(wire, &channel, json.RejectUnknownMembers(true)) != nil || channel.Schema != FunctionChannelSchema || len(channel.Entries) > MaxFunctionEntries {
		return FunctionChannel{}, ErrInvalid
	}
	previous := ""
	for _, entry := range channel.Entries {
		claim, err := entry.Claim()
		if err != nil {
			return FunctionChannel{}, err
		}
		key := functionReleaseKey(claim)
		if key <= previous {
			return FunctionChannel{}, ErrInvalid
		}
		previous = key
	}
	return channel, nil
}

func ReadFunctionChannel(ctx context.Context, location Location) (FunctionChannel, bool, error) {
	wire, _, found, err := location.get(ctx, FunctionChannelObject, MaxFunctionChannelBytes)
	if err != nil || !found {
		return FunctionChannel{}, found, err
	}
	channel, err := decodeFunctionChannel(wire)
	return channel, true, err
}

// ReadFunctionModule bounds allocation and checks the requested immutable digest.
// A module's bytes alone authorize neither its tenant nor execution.
func ReadFunctionModule(ctx context.Context, location Location, digest string) ([]byte, error) {
	decoded, err := hex.DecodeString(digest)
	if err != nil || len(decoded) != sha256.Size || digest != strings.ToLower(digest) {
		return nil, ErrInvalid
	}
	module, _, found, err := location.get(ctx, FunctionModuleObject(digest), release.MaxFunctionModuleBytes)
	if err != nil {
		return nil, err
	}
	if !found {
		return nil, fmt.Errorf("%w: function module is absent", ErrInvalid)
	}
	sum := sha256.Sum256(module)
	if len(module) == 0 || hex.EncodeToString(sum[:]) != digest {
		return nil, fmt.Errorf("%w: function module digest mismatch", ErrInvalid)
	}
	return module, nil
}

func PublishFunction(ctx context.Context, location Location, proof release.VerifiedFunction) error {
	if !proof.Valid() || location.Client == nil || location.Namespace == "" || location.Bucket == "" {
		return ErrInvalid
	}
	claim := proof.Claim()
	expectedBucket, err := BucketName(claim.Cell)
	if err != nil || location.Bucket != expectedBucket {
		return ErrInvalid
	}
	envelope, err := trust.DecodeEnvelope(proof.Envelope())
	if err != nil {
		return err
	}
	delegation, err := trust.DecodeEnvelope(proof.Delegation())
	if err != nil {
		return err
	}
	entry := FunctionRelease{}
	entry.Envelope, err = trust.EncodeEnvelope(envelope)
	if err != nil {
		return err
	}
	entry.Delegation, err = trust.EncodeEnvelope(delegation)
	if err != nil {
		return err
	}
	module := proof.Module()
	if len(module) == 0 || len(module) > release.MaxFunctionModuleBytes {
		return ErrInvalid
	}
	// If the create reply was lost, immutable readback decides whether it succeeded.
	if err := putFunctionModule(ctx, location, claim.Digest, module); err != nil {
		readback, readErr := ReadFunctionModule(ctx, location, claim.Digest)
		if readErr != nil || !bytes.Equal(readback, module) {
			return err
		}
	}
	readback, err := ReadFunctionModule(ctx, location, claim.Digest)
	if err != nil || !bytes.Equal(readback, module) {
		return fmt.Errorf("%w: published function module readback", ErrInvalid)
	}
	key := functionReleaseKey(claim)
	for range 8 {
		if !proof.Valid() {
			return trust.ErrExpired
		}
		wire, etag, found, err := location.get(ctx, FunctionChannelObject, MaxFunctionChannelBytes)
		if err != nil {
			return err
		}
		channel := FunctionChannel{Schema: FunctionChannelSchema, Entries: []FunctionRelease{}}
		if found {
			channel, err = decodeFunctionChannel(wire)
			if err != nil {
				return err
			}
		}
		index, exists := slices.BinarySearchFunc(channel.Entries, key, func(candidate FunctionRelease, target string) int {
			current, _ := candidate.Claim()
			return strings.Compare(functionReleaseKey(current), target)
		})
		if exists {
			current, _ := channel.Entries[index].Claim()
			if current.Sequence > claim.Sequence {
				return ErrStale
			}
			if current.Sequence == claim.Sequence {
				if bytes.Equal(channel.Entries[index].Envelope, entry.Envelope) && bytes.Equal(channel.Entries[index].Delegation, entry.Delegation) {
					return nil
				}
				return fmt.Errorf("%w: function sequence already names another signed release", ErrInvalid)
			}
			channel.Entries[index] = entry
		} else {
			if len(channel.Entries) >= MaxFunctionEntries {
				return fmt.Errorf("%w: function channel exceeds %d entries", ErrInvalid, MaxFunctionEntries)
			}
			channel.Entries = slices.Insert(channel.Entries, index, entry)
		}
		next, err := json.Marshal(channel, json.Deterministic(true))
		if err != nil {
			return err
		}
		if len(next) > MaxFunctionChannelBytes {
			return fmt.Errorf("%w: function channel exceeds 1 MiB", ErrInvalid)
		}
		if !proof.Valid() {
			return trust.ErrExpired
		}
		writeErr := location.put(ctx, FunctionChannelObject, next, etag)
		if writeErr == nil {
			return nil
		}
		// A successful write can lose its reply; accept only exact provenance readback.
		current, readErr := readPublishedFunction(ctx, location, key, entry)
		if readErr == nil && current {
			return nil
		}
		if !errors.Is(writeErr, ErrConflict) {
			return writeErr
		}
	}
	return ErrConflict
}

func putFunctionModule(ctx context.Context, location Location, digest string, module []byte) error {
	name := FunctionModuleObject(digest)
	_, err := location.Client.PutObject(ctx, objectstorage.PutObjectRequest{NamespaceName: new(location.Namespace), BucketName: new(location.Bucket), ObjectName: new(name), ContentLength: new(int64(len(module))), PutObjectBody: io.NopCloser(bytes.NewReader(module)), ContentType: new("application/wasm"), IfNoneMatch: new("*")})
	if httpStatus(err) == http.StatusPreconditionFailed {
		return ErrConflict
	}
	return err
}

func readPublishedFunction(ctx context.Context, location Location, key string, expected FunctionRelease) (bool, error) {
	channel, found, err := ReadFunctionChannel(ctx, location)
	if err != nil || !found {
		return false, err
	}
	for _, entry := range channel.Entries {
		claim, _ := entry.Claim()
		if functionReleaseKey(claim) == key {
			return bytes.Equal(entry.Envelope, expected.Envelope) && bytes.Equal(entry.Delegation, expected.Delegation), nil
		}
	}
	return false, nil
}

func TestFunctionChannelRejectsOversizedSourceAndCrossNamespaceModules(t *testing.T) {
	fixture := newFunctionChannelFixture(t)
	location, backend := functionObjectEndpoint(t)
	proof := fixture.proof(t, entityid.New(), "echo", 1, "first")
	backend.mu.Lock()
	backend.objects[ServiceBinaryObject("terrabase", proof.Claim().Digest)] = functionObject{data: proof.Module(), version: 1}
	backend.mu.Unlock()
	if _, err := ReadFunctionModule(t.Context(), location, proof.Claim().Digest); err == nil {
		t.Fatal("native service artifact substituted for function module")
	}
	backend.mu.Lock()
	backend.objects[FunctionModuleObject(proof.Claim().Digest)] = functionObject{data: bytes.Repeat([]byte{'x'}, release.MaxFunctionModuleBytes+1), version: 1}
	backend.mu.Unlock()
	if _, err := ReadFunctionModule(t.Context(), location, proof.Claim().Digest); err == nil {
		t.Fatal("oversized module accepted")
	}
	backend.mu.Lock()
	backend.objects[FunctionChannelObject] = functionObject{data: bytes.Repeat([]byte{' '}, MaxFunctionChannelBytes+1), version: 1}
	backend.mu.Unlock()
	if _, _, err := ReadFunctionChannel(t.Context(), location); err == nil {
		t.Fatal("oversized channel accepted")
	}
	entry := FunctionRelease{Envelope: proof.Envelope(), Delegation: proof.Delegation()}
	channel := FunctionChannel{Schema: FunctionChannelSchema, Entries: []FunctionRelease{entry, entry}}
	wire, err := json.Marshal(channel)
	if err != nil {
		t.Fatal(err)
	}
	backend.mu.Lock()
	backend.objects[FunctionChannelObject] = functionObject{data: wire, version: 2}
	backend.mu.Unlock()
	if _, _, err := ReadFunctionChannel(t.Context(), location); err == nil {
		t.Fatal("duplicate tenant/function index entry accepted")
	}
}

func verifyFunctionChannelEntry(t *testing.T, location Location, entry FunctionRelease, roots trust.Keyring, floor uint64) {
	t.Helper()
	claim, err := entry.Claim()
	if err != nil {
		t.Fatal(err)
	}
	module, err := ReadFunctionModule(t.Context(), location, claim.Digest)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := release.VerifyFunctionCurrent(entry.Envelope, entry.Delegation, module, roots, functionExpected(claim, floor), time.Now()); err != nil {
		t.Fatal(err)
	}
}

func functionExpected(claim release.FunctionClaim, floor uint64) release.FunctionExpectation {
	return release.FunctionExpectation{Environment: claim.Environment, Cell: claim.Cell, TenantID: claim.TenantID, FunctionID: claim.FunctionID, Revision: claim.Revision, Digest: claim.Digest, MinimumSequence: floor}
}

type functionChannelFixture struct {
	root  ed25519.PrivateKey
	roots trust.Keyring
}

func newFunctionChannelFixture(t *testing.T) functionChannelFixture {
	t.Helper()
	public, private, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	roots, err := trust.ParseKeyring(public)
	if err != nil {
		t.Fatal(err)
	}
	return functionChannelFixture{root: private, roots: roots}
}

func (fixture functionChannelFixture) proof(t *testing.T, tenant, function string, sequence uint64, revision string) release.VerifiedFunction {
	t.Helper()
	module := []byte("function module " + revision)
	digest := sha256.Sum256(module)
	claim := release.FunctionClaim{Schema: release.FunctionSchema, ABI: release.FunctionABI, TenantID: tenant, FunctionID: function, Revision: revision, Digest: hex.EncodeToString(digest[:]), Bytes: int64(len(module)), Environment: "production", Cell: "GRU", Sequence: sequence}
	public, private, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	keyID, err := trust.KeyID(public)
	if err != nil {
		t.Fatal(err)
	}
	encoded, err := trust.EncodeDelegatedPublicKey(public)
	if err != nil {
		t.Fatal(err)
	}
	now := time.Now().UTC().Truncate(time.Second)
	scope := release.FunctionScope(claim)
	delegation, err := trust.SignDelegation(trust.Delegation{SchemaVersion: trust.SchemaVersion, SubjectKeyID: keyID, SubjectPublicKey: encoded, Capabilities: []trust.Capability{{Domain: scope.Domain, DeploymentID: scope.DeploymentID, Cell: scope.Cell, Environment: scope.Environment, Role: scope.Role, Slots: []string{scope.Slot}, Actions: []string{"sign"}}}}, now.Add(-time.Minute), now.Add(2*time.Hour), fixture.root)
	if err != nil {
		t.Fatal(err)
	}
	envelope, err := release.SignFunctionClaim(claim, module, delegation, fixture.roots, private, now, time.Hour)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		t.Fatal(err)
	}
	grant, err := trust.EncodeEnvelope(delegation)
	if err != nil {
		t.Fatal(err)
	}
	proof, err := release.VerifyFunctionCurrent(wire, grant, module, fixture.roots, functionExpected(claim, sequence), now)
	if err != nil {
		t.Fatal(err)
	}
	return proof
}

type functionObject struct {
	data    []byte
	version int
}
type functionBucketBackend struct {
	mu                      sync.Mutex
	objects                 map[string]functionObject
	dropModule, dropChannel bool
	concurrent              []byte
}

func functionObjectEndpoint(t *testing.T) (Location, *functionBucketBackend) {
	t.Helper()
	backend := &functionBucketBackend{objects: map[string]functionObject{}}
	endpoint := httptest.NewServer(http.HandlerFunc(backend.serve))
	t.Cleanup(endpoint.Close)
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	provider := common.NewRawConfigurationProvider("ocid1.tenancy.oc1..function", "ocid1.user.oc1..function", "sa-saopaulo-1", "fp", string(pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})), nil)
	client, err := objectstorage.NewObjectStorageClientWithConfigurationProvider(provider)
	if err != nil {
		t.Fatal(err)
	}
	client.Configuration.RetryPolicy = new(common.NoRetryPolicy())
	client.Host = endpoint.URL
	return Location{Client: client, Namespace: "namespace", Bucket: "gru-1-head"}, backend
}

func (backend *functionBucketBackend) serve(w http.ResponseWriter, r *http.Request) {
	backend.mu.Lock()
	defer backend.mu.Unlock()
	_, name, ok := strings.Cut(r.URL.Path, "/o/")
	if !ok {
		http.Error(w, "route", 404)
		return
	}
	object, found := backend.objects[name]
	if r.Method == http.MethodGet {
		if !found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(404)
			_, _ = io.WriteString(w, `{"code":"ObjectNotFound","message":"absent"}`)
			return
		}
		w.Header().Set("ETag", fmt.Sprint(object.version))
		w.Header().Set("Content-Length", fmt.Sprint(len(object.data)))
		_, _ = w.Write(object.data)
		return
	}
	if r.Method != http.MethodPut {
		http.Error(w, "method", 405)
		return
	}
	if name == FunctionChannelObject && len(backend.concurrent) > 0 {
		backend.objects[name] = functionObject{data: bytes.Clone(backend.concurrent), version: object.version + 1}
		backend.concurrent = nil
		http.Error(w, "concurrent", 412)
		return
	}
	if r.Header.Get("If-None-Match") == "*" && found || r.Header.Get("If-Match") != "" && (!found || r.Header.Get("If-Match") != fmt.Sprint(object.version)) {
		http.Error(w, "changed", 412)
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, release.MaxFunctionModuleBytes+1))
	if err != nil {
		http.Error(w, "read", 400)
		return
	}
	if strings.HasPrefix(name, "releases/functions/modules/") && r.Header.Get("Content-Type") != "application/wasm" {
		http.Error(w, "module type", 400)
		return
	}
	backend.objects[name] = functionObject{data: body, version: object.version + 1}
	drop := name == FunctionChannelObject && backend.dropChannel || strings.HasPrefix(name, "releases/functions/modules/") && backend.dropModule
	if drop {
		if name == FunctionChannelObject {
			backend.dropChannel = false
		} else {
			backend.dropModule = false
		}
		connection, _, err := w.(http.Hijacker).Hijack()
		if err == nil {
			_ = connection.Close()
		}
		return
	}
	w.Header().Set("ETag", fmt.Sprint(object.version+1))
	w.WriteHeader(http.StatusOK)
}

func (claim FunctionClaim) Validate() error {
	if claim.Schema != FunctionSchema || claim.ABI != FunctionABI || !entityid.Valid(claim.TenantID) ||
		!serviceRolePattern.MatchString(claim.FunctionID) || !serviceRolePattern.MatchString(claim.Revision) ||
		!digestPattern.MatchString(claim.Digest) || claim.Bytes <= 0 || claim.Bytes > MaxFunctionModuleBytes ||
		len(claim.Capabilities) != 0 || !ValidEnvironment(claim.Environment) || !ValidRegion(claim.Cell) || claim.Sequence == 0 {
		return fmt.Errorf("%w: function ABI, identity, bytes, capabilities or release scope", ErrInvalidReceipt)
	}
	return nil
}

func VerifyFunctionCurrent(envelopeWire, delegationWire, module []byte, roots trust.Keyring,
	expected FunctionExpectation, now time.Time,
) (VerifiedFunction, error) {
	if err := expected.validate(); err != nil {
		return VerifiedFunction{}, err
	}
	if len(module) == 0 || len(module) > MaxFunctionModuleBytes {
		return VerifiedFunction{}, fmt.Errorf("%w: function module size", ErrInvalidReceipt)
	}
	claim, envelope, err := verifyFunctionReceipt(envelopeWire, delegationWire, roots, expected, now)
	if err != nil {
		return VerifiedFunction{}, err
	}
	// Retain the copy whose digest is checked, so callers cannot mutate admitted bytes.
	admitted := bytes.Clone(module)
	if err := claim.validateModule(admitted); err != nil {
		return VerifiedFunction{}, err
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return VerifiedFunction{}, err
	}
	return VerifiedFunction{claim: claim, module: admitted, envelope: bytes.Clone(envelopeWire),
		delegation: bytes.Clone(delegationWire), proof: proof}, nil
}

func (claim FunctionClaim) validateModule(module []byte) error {
	if err := claim.Validate(); err != nil {
		return err
	}
	if int64(len(module)) != claim.Bytes {
		return fmt.Errorf("%w: function module size mismatch", ErrInvalidReceipt)
	}
	digest := sha256.Sum256(module)
	if hex.EncodeToString(digest[:]) != claim.Digest {
		return fmt.Errorf("%w: function module digest mismatch", ErrInvalidReceipt)
	}
	return nil
}

// Valid rejects both forged zero values and authority that expired after admission.
func (verified VerifiedFunction) Valid() bool {
	return verified.proof.verified && time.Now().Before(verified.proof.expiresAt)
}

func (verified VerifiedFunction) Claim() FunctionClaim {
	claim := verified.claim
	claim.Capabilities = slices.Clone(claim.Capabilities)
	return claim
}

func (verified VerifiedFunction) Module() []byte         { return bytes.Clone(verified.module) }
func (verified VerifiedFunction) Envelope() []byte       { return bytes.Clone(verified.envelope) }
func (verified VerifiedFunction) Delegation() []byte     { return bytes.Clone(verified.delegation) }
func (verified VerifiedFunction) ExpiresAt() time.Time   { return verified.proof.expiresAt }
func (verified VerifiedFunction) EnvelopeSHA256() string { return verified.proof.envelopeSHA256 }

func (expected FunctionExpectation) validate() error {
	if !ValidEnvironment(expected.Environment) || !ValidRegion(expected.Cell) || !entityid.Valid(expected.TenantID) ||
		!serviceRolePattern.MatchString(expected.FunctionID) || !serviceRolePattern.MatchString(expected.Revision) ||
		!digestPattern.MatchString(expected.Digest) || expected.MinimumSequence == 0 {
		return fmt.Errorf("%w: invalid function expectation or missing durable sequence floor", ErrExpectationMismatch)
	}
	return nil
}

func verifyFunctionReceipt(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected FunctionExpectation, now time.Time,
) (FunctionClaim, trust.Envelope, error) {
	envelope, delegationEnvelope, err := decodeEnvelopePair(envelopeWire, delegationWire)
	if err != nil {
		return FunctionClaim{}, trust.Envelope{}, err
	}
	claim, err := decodeCanonicalPayload[FunctionClaim](envelope.Payload)
	if err != nil {
		return FunctionClaim{}, trust.Envelope{}, err
	}
	if err := claim.Validate(); err != nil {
		return FunctionClaim{}, trust.Envelope{}, err
	}
	if claim.Environment != expected.Environment || claim.Cell != expected.Cell || claim.TenantID != expected.TenantID ||
		claim.FunctionID != expected.FunctionID || claim.Revision != expected.Revision || claim.Digest != expected.Digest ||
		claim.Sequence < expected.MinimumSequence {
		return FunctionClaim{}, trust.Envelope{}, ErrExpectationMismatch
	}
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return FunctionClaim{}, trust.Envelope{}, fmt.Errorf("verify current function delegation: %w", err)
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, FunctionScope(claim), delegation, now, receiptPolicy()); err != nil {
		return FunctionClaim{}, trust.Envelope{}, fmt.Errorf("verify current function claim: %w", err)
	}
	return claim, envelope, nil
}

