func (pins *ReleasePins) ValidateFresh(updatedAt, now time.Time) error {
	if err := pins.Validate(); err != nil {
		return err
	}
	age := now.Sub(updatedAt)
	if updatedAt.IsZero() || age > MaxPinAge || age < -PinRefreshInterval {
		return fmt.Errorf("%w: release pin inventory timestamp %s is missing, stale, or ahead of the clock", ErrInvalid, updatedAt)
	}
	return nil
}

// PinKeys refuses a partial inventory: only the watcher's nil entry proves
// that all initial keys arrived before CI can use them to prune releases.
func PinKeys(ctx context.Context, kv jetstream.KeyValue, filter string) ([]string, error) {
	watcher, err := kv.WatchFiltered(ctx, []string{filter}, jetstream.MetaOnly(), jetstream.IgnoreDeletes())
	if err != nil {
		return nil, err
	}
	defer watcher.Stop()
	var keys []string
	for {
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case entry, open := <-watcher.Updates():
			if !open {
				return nil, errors.New("release pin watcher closed before inventory completed")
			}
			if entry == nil {
				if err := ctx.Err(); err != nil {
					return nil, err
				}
				return keys, nil
			}
			keys = append(keys, entry.Key())
		}
	}
}

func (pins *ReleasePins) Equal(other *ReleasePins) bool {
	if pins == nil || other == nil {
		return pins == other
	}
	return slices.Equal(pins.Rollback, other.Rollback) && slices.Equal(pins.KnownBad, other.KnownBad)
}

// Validate refuses an absent inventory or digests the pruning script would
// silently skip. Status comes from a remote bucket, not trusted cell state.
func (pins *ReleasePins) Validate() error {
	if pins == nil {
		return fmt.Errorf("%w: release pins are missing", ErrInvalid)
	}
	for _, digests := range [][]string{pins.Rollback, pins.KnownBad} {
		for _, digest := range digests {
			if _, err := hex.DecodeString(digest); err != nil || len(digest) != 64 || strings.ToLower(digest) != digest {
				return fmt.Errorf("%w: release pin %q", ErrInvalid, digest)
			}
		}
	}
	return nil
}

type pinWatchKV struct {
	jetstream.KeyValue
	watcher *pinWatcher
	err     error
	filters []string
}

func (kv *pinWatchKV) WatchFiltered(_ context.Context, filters []string, _ ...jetstream.WatchOpt) (jetstream.KeyWatcher, error) {
	kv.filters = slices.Clone(filters)
	return kv.watcher, kv.err
}

type pinWatcher struct {
	updates chan jetstream.KeyValueEntry
	stopped bool
}

func (watcher *pinWatcher) Updates() <-chan jetstream.KeyValueEntry { return watcher.updates }
func (watcher *pinWatcher) Stop() error {
	watcher.stopped = true
	return nil
}

type pinEntry struct {
	jetstream.KeyValueEntry
	key    string
	cancel context.CancelFunc
}

func (entry pinEntry) Key() string {
	if entry.cancel != nil {
		entry.cancel()
	}
	return entry.key
}

