func New(spec Spec, now time.Time) (Record, error) {
	if now.IsZero() || spec.StartedAt.After(now) {
		return Record{}, fmt.Errorf("%w: start time", ErrInvalid)
	}
	if slices.Contains(spec.KnownBad, spec.ToDigest) {
		return Record{}, ErrKnownBad
	}
	waves, err := PlanWaves(spec.Units, spec.Policy)
	if err != nil {
		return Record{}, err
	}
	policyDigest, err := spec.Policy.Digest()
	if err != nil {
		return Record{}, err
	}
	units := make(map[string]UnitProgress, len(spec.Units))
	for _, unit := range spec.Units {
		units[unit.ID] = UnitProgress{State: UnitPending, Group: unit.Group, Seed: unit.Seed}
	}
	for wave, ids := range waves {
		for _, id := range ids {
			progress := units[id]
			progress.Wave = wave
			units[id] = progress
		}
	}
	knownBad := slices.Clone(spec.KnownBad)
	slices.Sort(knownBad)
	started := spec.StartedAt
	if started.IsZero() {
		started = now
	}
	record := Record{
		SchemaVersion: SchemaVersion, RolloutID: spec.RolloutID, Kind: spec.Kind, Cell: spec.Cell,
		FromDigest: spec.FromDigest, ToDigest: spec.ToDigest, Policy: spec.Policy, PolicyDigest: policyDigest,
		Phase: PhasePending, Waves: waves, Units: units, KnownBad: slices.Compact(knownBad),
		StartedAt: started.UTC(), PhaseStartedAt: now.UTC(), AuthorityEpoch: spec.AuthorityEpoch,
	}
	if err := record.Validate(); err != nil {
		return Record{}, err
	}
	return record, nil
}

func Apply(record Record, event Event) (Record, error) {
	if err := record.Validate(); err != nil {
		return Record{}, err
	}
	if event.At.IsZero() || len(event.Reason) > maxReason {
		return Record{}, fmt.Errorf("%w: event time or reason", ErrInvalid)
	}
	if record.Phase.Terminal() {
		return Record{}, ErrTerminal
	}
	next := record.Clone()
	at := event.At.UTC()
	if completionEvent(event.Kind) || event.Kind == EventStart {
		// A completion that arrives after its phase deadline must not erase
		// that deadline: enforce it first, exactly as a tick at the same
		// instant would, and drop the late completion if it fired.
		phase, wave := next.Phase, next.WaveIndex
		next.tick(at)
		if next.Phase != phase || next.WaveIndex != wave {
			if err := next.Validate(); err != nil {
				return Record{}, err
			}
			return next, nil
		}
	}
	var err error
	switch event.Kind {
	case EventStart:
		err = next.start(at)
	case EventPreflightPassed:
		err = next.preflightPassed(at)
	case EventPreflightFailed:
		err = next.requirePhase(PhasePreflight)
		if err == nil {
			next.finish(PhaseAborted, at, reasonOr(event.Reason, "preflight failed"))
		}
	case EventPrepared:
		err = next.prepared(event.Unit, at)
	case EventHealthy:
		err = next.healthy(event.Unit, event.Health, at)
	case EventUnhealthy, EventHeld:
		// A held forward step rolls back like an unhealthy one; rollback
		// itself, not the forward unit, is what freezes for a human.
		err = next.failed(event.Unit, at, reasonOr(event.Reason, string(event.Kind)))
	case EventRollbackServing:
		err = next.rollbackServing(event.Unit, at)
	case EventRollbackHeld:
		err = next.rollbackHeld(event.Unit, at, reasonOr(event.Reason, "rollback held"))
	case EventTick:
		next.tick(at)
	case EventAbort:
		err = next.abort(at, reasonOr(event.Reason, "operator abort"))
	case EventFreeze:
		if next.Phase == PhaseFrozen {
			return Record{}, ErrInvalidTransition
		}
		next.enter(PhaseFrozen, at, time.Time{}, reasonOr(event.Reason, "frozen"))
	case EventResume:
		err = next.resume(at, event.Left)
	default:
		err = fmt.Errorf("%w: event kind", ErrInvalid)
	}
	if err != nil {
		return Record{}, err
	}
	if err := next.Validate(); err != nil {
		return Record{}, err
	}
	return next, nil
}

func (record *Record) enter(phase Phase, at, deadline time.Time, reason string) {
	if (phase == PhasePreflight || phase.preparing() || phase.soaking()) && deadline.After(record.StartedAt.Add(ObservationBudget)) {
		deadline = record.StartedAt.Add(ObservationBudget)
	}
	record.Phase = phase
	record.PhaseStartedAt = at
	record.PhaseDeadline = deadline
	record.Reason = boundReason(reason)
}

func (record *Record) finish(phase Phase, at time.Time, reason string) {
	record.enter(phase, at, time.Time{}, reason)
}

func (record *Record) abort(at time.Time, reason string) error {
	switch {
	case record.Phase == PhasePending || record.Phase == PhasePreflight:
		record.finish(PhaseAborted, at, reason)
	case record.Phase.preparing() || record.Phase.soaking():
		record.startRollback(at, reason)
	default:
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	return nil
}

func (record Record) Validate() error {
	if record.SchemaVersion != SchemaVersion || !entityid.Valid(record.RolloutID) || !record.Kind.valid() ||
		!tokenRE.MatchString(record.Cell) || !digestRE.MatchString(record.FromDigest) || !digestRE.MatchString(record.ToDigest) ||
		record.FromDigest == record.ToDigest || record.AuthorityEpoch == 0 || record.StartedAt.IsZero() ||
		record.PhaseStartedAt.IsZero() || len(record.Reason) > maxReason || len(record.KnownBad) > MaxKnownBad {
		return fmt.Errorf("%w: record identity", ErrInvalid)
	}
	if err := record.Policy.Validate(); err != nil {
		return err
	}
	if digest, err := record.Policy.Digest(); err != nil || digest != record.PolicyDigest {
		return fmt.Errorf("%w: policy digest", ErrInvalid)
	}
	switch record.Phase {
	case PhasePending, PhasePreflight, PhaseCanary, PhaseCanarySoak, PhaseBatch, PhaseBatchSoak,
		PhaseComplete, PhaseRollingBack, PhaseFrozen, PhaseAborted, PhaseRolledBack:
	default:
		return fmt.Errorf("%w: phase", ErrInvalid)
	}
	if len(record.Waves) == 0 || len(record.Units) == 0 || len(record.Units) > MaxUnits ||
		record.WaveIndex < 0 || record.WaveIndex >= len(record.Waves) {
		return fmt.Errorf("%w: waves", ErrInvalid)
	}
	seen := make(map[string]struct{}, len(record.Units))
	for wave, ids := range record.Waves {
		if len(ids) == 0 {
			return fmt.Errorf("%w: empty wave", ErrInvalid)
		}
		for _, id := range ids {
			progress, exists := record.Units[id]
			if _, duplicate := seen[id]; duplicate || !exists || progress.Wave != wave || !tokenRE.MatchString(progress.Group) {
				return fmt.Errorf("%w: wave unit %q", ErrInvalid, id)
			}
			seen[id] = struct{}{}
		}
	}
	if len(seen) != len(record.Units) {
		return fmt.Errorf("%w: unit outside every wave", ErrInvalid)
	}
	for _, id := range record.RollbackOrder {
		if _, exists := record.Units[id]; !exists {
			return fmt.Errorf("%w: rollback unit %q", ErrInvalid, id)
		}
	}
	for _, digest := range record.KnownBad {
		if !digestRE.MatchString(digest) {
			return fmt.Errorf("%w: known-bad digest", ErrInvalid)
		}
	}
	if slices.Contains(record.KnownBad, record.FromDigest) {
		return fmt.Errorf("%w: rollback target is known bad", ErrInvalid)
	}
	return record.validatePhaseUnits()
}

// validatePhaseUnits rejects phase and unit-state contradictions that Apply
// never produces, so a record built outside Apply is refused at the storage
// boundary instead of driving effects.
func (record Record) validatePhaseUnits() error {
	for _, id := range record.Waves[record.WaveIndex] {
		state := record.Units[id].State
		if record.Phase.soaking() && state != UnitSoaking ||
			record.Phase.preparing() && state != UnitPreparing && state != UnitSoaking {
			return fmt.Errorf("%w: phase %s contradicts unit %q in state %s", ErrInvalid, record.Phase, id, state)
		}
	}
	if record.Phase == PhaseRollingBack && record.rollbackHead() == "" {
		return fmt.Errorf("%w: rolling back without a unit to roll back", ErrInvalid)
	}
	return nil
}

func (record Record) abortedBeforeUpdate() bool {
	if record.Phase != PhaseAborted || len(record.RollbackOrder) != 0 {
		return false
	}
	for _, progress := range record.Units {
		if progress.State != UnitPending {
			return false
		}
	}
	return true
}

